import type { EngineInterface, Register } from 'claude-code'

import {
  API,
  CALM,
  SHADE_COLOR,
  WARMUP,
  WINDOW_HOURS,
  assess,
  isNagDue,
  isSlowDue,
  pick,
  quote,
  readLastNag,
  readLastSlow,
  slowDowns,
  slowQuote,
  slowText,
  statusText,
  usageLine,
  usageView,
  weekly,
} from './burn'
import type { Limit, UsageView } from './burn'

const LAST_NAG = 'lastNag'
const LAST_SLOW = 'lastSlow'
// Rate limits only change when usage moves, so a timer keeps the countdown and nags going while idle.
const RECHECK_MS = 60_000
// How long a nag toast stays, set here so it doesn't follow changes to the default.
const TOAST_MS = 4_000
// Surfaces that draw the coloured row under the prompt hint; any other gets the plain status line.
const COLOUR_SURFACES: readonly string[] = ['terminal', 'desktop']

// The latest reading, re-assessed by the timer between measures.
let latest: readonly Limit[] = []
// What the coloured row under the prompt hint draws; undefined draws nothing.
let view: UsageView | undefined

async function check($: EngineInterface, limits: readonly Limit[]) {
  latest = limits
  const now = await $.clock.now()
  const burn = assess(weekly(limits), now)
  const slow = slowDowns(limits, now, burn)

  view = usageView(limits, now, burn, slow)
  $.ui.invalidate('ui.render')
  // The plain line is only needed where some surface can't draw the coloured row.
  const surfaces = await $.session.surfaces()
  const plainNeeded = surfaces.length === 0 || surfaces.some(s => !COLOUR_SURFACES.includes(s))
  $.ui.status(plainNeeded ? usageLine(limits, now, burn, slow) : undefined)

  // Kept in $.store so a nag isn't repeated by every new session.
  if (burn !== null) {
    const last = readLastNag(await $.store.get(LAST_NAG))
    if (!isNagDue(burn, now, last)) return
    $.ui.toast(quote(burn, now), { timeoutMs: TOAST_MS })
    await $.store.set(LAST_NAG, { at: now, tier: burn.tier })
    return
  }

  // No burn tier applies: one slow-down toast at most, the session first.
  const lastSlow = readLastSlow(await $.store.get(LAST_SLOW))
  const due = slow.find(p => isSlowDue(p, now, lastSlow))
  if (due === undefined) return
  $.ui.toast(slowQuote(due, now), { timeoutMs: TOAST_MS })
  await $.store.set(LAST_SLOW, { ...lastSlow, [due.kind]: now })
}

// Checks run one after another: a measure and the timer's tick could otherwise both read the
// store before either writes it, and toast the same nag twice.
let queue: Promise<void> = Promise.resolve()

// A nag is never worth breaking the session for: a failed check is dropped.
function safeCheck($: EngineInterface, limits: readonly Limit[]): Promise<void> {
  queue = queue.then(() => check($, limits)).catch(() => {
    // Nothing to recover; the next measure or tick tries again.
  })
  return queue
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const started = await next(e)
    await $.command.register({ name: 'burn', description: 'How much of the weekly limit is left to burn' })
    // Empty until the first API response of the session; session.measure follows.
    await safeCheck($, (await $.session.usage()).rateLimits)
    $.clock.every(RECHECK_MS, () => void safeCheck($, latest))
    return started
  })

  on('session.measure', async ($, e, next) => {
    if (e.changed.includes('rateLimits')) await safeCheck($, e.rateLimits)
    return next(e)
  })

  // The usage line in colour, on its own row under Claude Code's hint line, which is drawn unchanged.
  on('ui.render', { component: 'PromptHint' }, async ($, e, next) => {
    const engine = await next(e)
    const shown = view
    if (shown === undefined) return engine
    const { Box, Text } = $.ui.resolve(e)
    return (
      <Box flexDirection="column">
        {engine}
        {/* The marker rides on the first gauge, so a narrow terminal never leaves it alone on a row. */}
        <Box flexWrap="wrap" columnGap={3}>
          {shown.gauges.map((g, i) => {
            const gaugeText = <Text color={SHADE_COLOR[g.shade]}>{g.text}</Text>
            const marker = i === 0 ? shown.marker : undefined
            if (marker === undefined) return <Text wrap="truncate-end">{gaugeText}</Text>
            return (
              <Text wrap="truncate-end">
                <Text color={SHADE_COLOR[marker.shade]}>{`${marker.text} `}</Text>
                {gaugeText}
              </Text>
            )
          })}
        </Box>
      </Box>
    )
  })

  on('command.run', { command: 'burn' }, async $ => {
    const now = await $.clock.now()
    const usage = await $.session.usage()
    const limit = weekly(usage.rateLimits)
    if (limit === undefined) {
      // Subscriptions report the weekly window with the first answer; still none after one means an API key.
      const hasAnswered = (usage.context.tokens ?? 0) > 0 || (usage.cost?.usd ?? 0) > 0
      return { text: pick(hasAnswered ? API : WARMUP, now) }
    }
    const burn = assess(limit, now)
    if (burn !== null) return { text: `${statusText(burn)}\n${quote(burn, now)}` }
    const fast = slowDowns(usage.rateLimits, now, burn)[0]
    if (fast !== undefined) return { text: `${slowText(fast)}\n${slowQuote(fast, now)}` }
    return { text: `${Math.round(100 - limit.percentUsed)}% of the week left. ${pick(CALM, now).replaceAll('{window}', String(WINDOW_HOURS))}` }
  })
}

