export type Limit = { kind: string; percentUsed: number; resetsAt?: string }
export type Tier = 'smoulder' | 'blaze' | 'inferno'
export type Burn = { tier: Tier; left: number; msLeft: number }

const HOUR = 60 * 60 * 1000

// How long before the reset each tier starts, how often it may nag, and the share of the week
// that must still be left for it to nag at all (less as the reset nears).
const TIERS: { tier: Tier; within: number; every: number; minLeft: number }[] = [
  { tier: 'inferno', within: 10 * HOUR, every: 30 * 60 * 1000, minLeft: 5 },
  { tier: 'blaze', within: 24 * HOUR, every: 2 * HOUR, minLeft: 15 },
  { tier: 'smoulder', within: 72 * HOUR, every: 6 * HOUR, minLeft: 25 },
]

const QUOTES: Record<Tier, string[]> = {
  smoulder: [
    'Burn, baby, burn. {left} of your week is just sitting there.',
    "Tokens don't roll over. Neither does regret.",
    "Your weekly quota called. It's feeling unloved.",
    'Unused tokens are just compute crying quietly.',
    'Light my fire: {left} left, reset in {time}.',
    "{left} of your week is still in the fridge. It expires in {time}.",
    "Your tokens are like gym membership: paid for and unused.",
    "Fun fact: unused tokens don't go to token heaven.",
    "Your context window is looking a bit empty. Feed it.",
    "Somewhere, a backlog is waiting for you. {left} could clear it.",
    "Claude is getting bored. Give it a refactor.",
  ],
  blaze: [
    'Disco inferno: {left} left and under a day to go.',
    "Use it or lose it. And you're about to lose it.",
    'Somewhere a GPU is idle because of you.',
    'We didn\'t start the fire, but {left} of your week says you should.',
    'Ship it like the reset is tomorrow. Because it is.',
    "{left} left and {time} to go. Even your linter is judging you.",
    "That TODO from 2023? Now's the time. {left} says so.",
    "Pretend it's Friday at 5 pm and the demo is Monday.",
    "Your weekly quota is packing its bags. {time} until it leaves.",
    "Write the tests you promised yourself. You have {left} of a week to do it.",
    "Under a day left. Ask Claude something ambitious.",
  ],
  inferno: [
    'BURN BABY BURN! {left} left, reset in {time}!',
    'Last call at the token bar. Order big.',
    "It's the final countdown: {time} to burn {left}.",
    'Refactor something. Anything. Now.',
    'Great balls of fire! {left} still unspent!',
    "{time} left. This is not a drill. {left} still unburned!",
    "Open every repo. Fix everything. GO.",
    "The tokens are melting. {left} gone in {time}.",
    "Spend it like it's the last day of vacation money.",
    "Ask Claude to rewrite it in Rust. You have {left} to spare.",
    "Midnight sale on tokens: everything must go in {time}.",
  ],
}

export function weekly(limits: readonly Limit[]): Limit | undefined {
  return limits.find(l => l.kind === 'seven_day')
}

// The windows the usage line shows, in order, under the names /usage gives them.
// The one place a window gets its name: the gauges and the slow-down text both read it.
const LABEL: Record<PaceKind, string> = { five_hour: 'session', seven_day: 'week' }
const SHOWN: readonly PaceKind[] = ['five_hour', 'seven_day']
const GAUGE_CELLS = 8

// A fuel gauge of how much of a window is used: ▰ spent, ▱ still to burn.
export function gauge(percentUsed: number): string {
  const spent = Math.min(GAUGE_CELLS, Math.max(0, Math.round((percentUsed / 100) * GAUGE_CELLS)))
  return '▰'.repeat(spent) + '▱'.repeat(GAUGE_CELLS - spent)
}

// What colours a part of the usage line: calm, a burn tier, or the slow-down nudge.
export type Shade = 'calm' | Tier | 'slow'

// Theme keys, so the colours follow the person's light or dark theme. Plan and auto-accept
// colours are left out: Claude Code's own mode pills use them on the same rows.
export const SHADE_COLOR: Record<Shade, 'inactive' | 'warning' | 'claude' | 'error' | 'suggestion'> = {
  calm: 'inactive',
  smoulder: 'warning',
  blaze: 'claude',
  inferno: 'error',
  slow: 'suggestion',
}

export type LinePart = { text: string; shade: Shade }
// The usage line: an optional marker ahead of it, then one gauge per window.
export type UsageView = { marker?: LinePart; gauges: LinePart[] }

const EXTINGUISHER = '🧯'

// The usage line in coloured parts: a marker (the tier's flames near the weekly reset, or the
// extinguisher for a window used too fast), then each window's gauge and reset. Only the week
// gauge takes the burn tier's colour; a window used too fast takes the slow-down colour.
// A window whose reset has passed is a stale reading and is left out; with none left, there is no line.
export function usageView(limits: readonly Limit[], now: number, burn: Burn | null, slow: readonly Pace[] = []): UsageView | undefined {
  const gauges = SHOWN.flatMap((kind): LinePart[] => {
    const limit = limits.find(l => l.kind === kind)
    if (limit === undefined) return []
    const msLeft = limit.resetsAt === undefined ? NaN : Date.parse(limit.resetsAt) - now
    if (msLeft <= 0) return []
    const reset = Number.isNaN(msLeft) ? '' : ` ↻ ${formatLeft(msLeft)}`
    const shade: Shade = burn && kind === 'seven_day' ? burn.tier : slow.some(p => p.kind === kind) ? 'slow' : 'calm'
    return [{ text: `${LABEL[kind]} ${gauge(limit.percentUsed)} ${Math.round(limit.percentUsed)}%${reset}`, shade }]
  })
  if (gauges.length === 0) return undefined
  if (burn) return { marker: { text: FLAMES[burn.tier], shade: burn.tier }, gauges }
  if (gauges.some(g => g.shade === 'slow')) return { marker: { text: EXTINGUISHER, shade: 'slow' }, gauges }
  return { gauges }
}

// The same line as plain text, for surfaces that can't draw the coloured row.
export function usageLine(limits: readonly Limit[], now: number, burn: Burn | null, slow: readonly Pace[] = []): string | undefined {
  const view = usageView(limits, now, burn, slow)
  if (view === undefined) return undefined
  return (view.marker ? `${view.marker.text} ` : '') + view.gauges.map(g => g.text).join('   ')
}

export function assess(limit: Limit | undefined, now: number): Burn | null {
  if (limit?.resetsAt === undefined) return null
  const msLeft = Date.parse(limit.resetsAt) - now
  if (Number.isNaN(msLeft) || msLeft <= 0) return null
  // Tiers are ordered tightest first, so the first match is the hottest.
  const match = TIERS.find(t => msLeft <= t.within)
  // The exact share left meets the threshold, so 4.6% doesn't pass as 5%; only the shown number is rounded.
  const exactLeft = 100 - limit.percentUsed
  if (match === undefined || exactLeft < match.minLeft) return null
  return { tier: match.tier, left: Math.round(exactLeft), msLeft }
}

export function nagEvery(tier: Tier): number {
  return TIERS.find(t => t.tier === tier)?.every ?? 6 * HOUR
}

// The warning window: the widest tier's reach before the reset.
export const WINDOW_HOURS = Math.max(...TIERS.map(t => t.within)) / HOUR

export type LastNag = { at: number; tier: Tier }

// Store values are untrusted (older versions, hand edits): anything malformed counts as no nag yet.
export function readLastNag(value: unknown): LastNag | undefined {
  if (typeof value !== 'object' || value === null) return undefined
  const { at, tier } = value as Record<string, unknown>
  if (typeof at !== 'number' || !Number.isFinite(at)) return undefined
  if (!TIERS.some(t => t.tier === tier)) return undefined
  return { at, tier: tier as Tier }
}

// Tiers only get hotter as the reset nears, so a tier change always nags; otherwise once per the tier's interval.
export function isNagDue(burn: Burn, now: number, last: LastNag | undefined): boolean {
  if (last === undefined || last.tier !== burn.tier) return true
  return now - last.at >= nagEvery(burn.tier)
}

export function formatLeft(ms: number): string {
  const hours = Math.floor(ms / HOUR)
  const days = Math.floor(hours / 24)
  if (days > 0) return `${days}d ${hours % 24}h`
  if (hours > 0) return `${hours}h ${Math.floor((ms % HOUR) / 60000)}m`
  return `${Math.max(1, Math.floor(ms / 60000))}m`
}

// Picks a line that changes every minute, so repeat nags don't repeat lines.
export function pick(lines: readonly string[], now: number): string {
  return lines[Math.floor(now / 60000) % lines.length] ?? lines[0] ?? ''
}

export function quote(burn: Burn, now: number): string {
  return pick(QUOTES[burn.tier], now)
    .replaceAll('{left}', `${burn.left}%`)
    .replaceAll('{time}', formatLeft(burn.msLeft))
}

// /burn outside the warning window.
export const CALM = [
  "The fire is just a pilot light for now. Go build something.",
  "Plenty of fuel in the tank. I'll start yelling {window} h before the reset.",
  "Relax. Your tokens are safe… for now. 😈",
  "Too early to panic. Come back in a few days.",
  "The kindling is stacked. The match is ready. Not yet, though.",
  "I'm on standby. Spend wisely, and I'll keep quiet.",
]

// /burn when Claude has answered but no weekly limit came back: an API key, pay per token.
export const API = [
  "No weekly limit here. You pay per token, so I'm the one who should be scared. 💸",
  "API user detected. There's no quota to burn, only your credit card.",
  "You don't have a weekly limit. You have an invoice.",
  "Nothing resets for you. Your bill just keeps going up.",
  "I'm a weekly-limit nagger with no weekly limit. Existential crisis. 🔥🫠",
  "Every token counts on your bill. Burn responsibly.",
]

// /burn before the session's first answer, when there is no reading yet.
export const WARMUP = [
  "I can't see your fuel gauge yet. Say something to Claude and I'll take a look.",
  "Warming up the matches… send a prompt and I'll check your tank.",
  "No smoke without fire, and no reading without a prompt. Ask Claude anything.",
  "I'm blind until Claude answers once. Go on, poke it.",
  "Still lighting the stove. One prompt and I'll know how much you've got to burn.",
]

const FLAMES: Record<Tier, string> = { smoulder: '🔥', blaze: '🔥🔥', inferno: '🔥🔥🔥' }

export function statusText(burn: Burn): string {
  return `${FLAMES[burn.tier]} ${burn.left}% of the week left · resets in ${formatLeft(burn.msLeft)}`
}

// --- Slow down: a window used much faster than it refills ---

export type PaceKind = 'five_hour' | 'seven_day'
export type Pace = { kind: PaceKind; used: number; msLeft: number }

// For each window: its length, how much must be used before pace counts, and how far used %
// must run ahead of elapsed %. A pace of 1.5 runs dry with a third of the window still to go,
// so the reset is always far off when it fires (used < 100 means elapsed < 2/3 of the window).
const SLOW: { kind: PaceKind; windowMs: number; minUsed: number; pace: number }[] = [
  { kind: 'five_hour', windowMs: 5 * HOUR, minUsed: 50, pace: 1.5 },
  { kind: 'seven_day', windowMs: 7 * 24 * HOUR, minUsed: 40, pace: 1.5 },
]
// The least time between two slow-down toasts, of either window.
export const SLOW_GAP_MS = 30 * 60 * 1000

export function pace(limit: Limit | undefined, now: number): Pace | null {
  const rule = SLOW.find(r => r.kind === limit?.kind)
  if (rule === undefined || limit?.resetsAt === undefined) return null
  const msLeft = Date.parse(limit.resetsAt) - now
  if (Number.isNaN(msLeft) || msLeft <= 0 || msLeft >= rule.windowMs) return null
  const used = limit.percentUsed
  const elapsed = 100 * (1 - msLeft / rule.windowMs)
  if (used < rule.minUsed || used >= 100 || used < rule.pace * elapsed) return null
  return { kind: rule.kind, used: Math.round(used), msLeft }
}

// The windows used too fast, session first. Never while a burn tier applies: the mod doesn't say
// "burn" and "slow down" at once, so a burn verdict silences the nudge for both windows.
export function slowDowns(limits: readonly Limit[], now: number, burn: Burn | null): Pace[] {
  if (burn !== null) return []
  return SLOW.flatMap(r => {
    const p = pace(limits.find(l => l.kind === r.kind), now)
    return p ? [p] : []
  })
}

// When each window last got a slow-down toast.
export type LastSlow = Partial<Record<PaceKind, number>>

// Store values are untrusted: anything malformed counts as no toast yet.
export function readLastSlow(value: unknown): LastSlow {
  if (typeof value !== 'object' || value === null) return {}
  const out: LastSlow = {}
  for (const { kind } of SLOW) {
    const at = (value as Record<string, unknown>)[kind]
    if (typeof at === 'number' && Number.isFinite(at)) out[kind] = at
  }
  return out
}

// Once per window (the last toast for it came before this window began), and never within
// SLOW_GAP_MS of another slow-down toast.
export function isSlowDue(p: Pace, now: number, last: LastSlow): boolean {
  const rule = SLOW.find(r => r.kind === p.kind)
  if (rule === undefined) return false
  const windowStart = now + p.msLeft - rule.windowMs
  const mine = last[p.kind]
  if (mine !== undefined && mine >= windowStart) return false
  const latestAny = Math.max(-Infinity, ...Object.values(last))
  return now - latestAny >= SLOW_GAP_MS
}

const SLOW_QUOTES: Record<PaceKind, string[]> = {
  five_hour: [
    'Easy there, bro. {used} of your session gone and {time} to the reset. Hydrate, touch grass.',
    'Whoa, cowboy. {used} of the session already, {time} to go. Pace yourself.',
    '{used} of your session in record time. The fire marshal would like a word.',
    'Slow burn, baby. {used} gone and the session resets in {time}.',
    "{used} already? Stretch, grab a coffee, let the tokens cool for a bit.",
    "It's a marathon, not a sprint. {used} spent, {time} on the clock.",
    'Even I think that\'s too hot. {used} of your session, {time} to the reset. 🧯',
    'Have a life. Touch grass. The session resets in {time}.',
    'Go outside. The sun misses you. {used} of the session can wait.',
    'Drink some water. {used} of your session is gone and you look thirsty.',
    'Call your mom. She asked about you. The session refills in {time}.',
    'Pet a dog. Any dog. {used} of the session deserves a break.',
    'Nap time. {used} of your session gone, {time} to the reset.',
    'Your chair needs a break too. Stand up for {time}.',
    "The tokens aren't going anywhere. Well, {used} of them did.",
  ],
  seven_day: [
    "Easy, tiger. {used} of the week gone and it doesn't reset for {time}.",
    '{used} of your week already? Save some fire for the weekend.',
    'At this pace your week ends before the week does. {time} to the reset.',
    'Slow down, champ. {used} spent, {time} to go. Even dragons pace their fire.',
    'Who are you and what did you do with my quota? {used} gone, {time} left.',
    '{used} of the week, {time} to go. Maybe let Claude think before it types.',
    'Rationing mode: {used} of the week is toast and the reset is {time} away.',
    "I usually yell 'burn'. Today it's 'hold my extinguisher'. {used} gone, {time} left. 🧯",
    'Have a life. Touch grass. The week resets in {time}.',
    'Go outside. The sun has been asking about you.',
    '{used} of the week gone. Drink water, eat a vegetable, come back later.',
    'Call your mom. Tell her you used {used} of your week already.',
    'Pet a dog. Read a book. The week still has {time} to go.',
    'Take a nap. Your weekly quota will thank you in {time}.',
    "Your keyboard needs a weekend. {used} of the week says so.",
    "The tokens aren't going anywhere. Neither is the reset, for {time}.",
  ],
}

export function slowQuote(p: Pace, now: number): string {
  return pick(SLOW_QUOTES[p.kind], now)
    .replaceAll('{used}', `${p.used}%`)
    .replaceAll('{time}', formatLeft(p.msLeft))
}

export function slowText(p: Pace): string {
  return `${EXTINGUISHER} ${p.used}% of the ${LABEL[p.kind]} gone · resets in ${formatLeft(p.msLeft)}`
}

